(71, 3, 'Sửa Sản Phẩm', 'admin/product_form.php', 'Cập nhật sản phẩm: iPhone 16 128GB', '{\"id\":59,\"name\":\"iPhone 16 128GB\",\"brand\":\"Apple\",\"price\":\"22990000\",\"sale_price\":\"21990000.00\",\"ram\":\"8GB\",\"rom\":\"128GB\",\"image\":\"https:\\/\\/cdn2.cellphones.com.vn\\/insecure\\/rs:fill:358:358\\/q:90\\/plain\\/https:\\/\\/cellphones.com.vn\\/media\\/catalog\\/product\\/i\\/p\\/iphone-16-xanh-luu-ly_1.png\",\"description\":\"iPhone 16  – Siêu phẩm chính hãng giá tốt\\r\\nDòng flagship năm 2025 của Apple không chỉ gây chú ý nhờ cấu hình mạnh mà còn nhờ chính sách phân phối chính hãng tại Việt Nam. Thế hệ iPhone này được nhiều người dùng tìm kiếm vì mang lại giá trị sử dụng bền vững cùng hiệu suất ổn định.\\r\\nĐột phá về hiệu năng, camera và thiết kế Titanium thế hệ mới\\r\\nĐiện thoại iPhone 16 Pro Max là mẫu smartphone hội tụ sức mạnh và sự tinh tế trong từng chi tiết khi sở hữu chip A18 Pro sản xuất trên tiến trình hiện đại. Nhờ đó, máy được nâng cấp đáng kể về hiệu suất CPU và GPU, cho khả năng xử lý nhanh hơn so với A17 Pro, hỗ trợ quay chụp, edit, chơi game 3D ổn định. \",\"created_at\":\"2025-12-27 16:03:32\",\"brand_id\":1,\"category_id\":1,\"specs\":\"{\\\"screen\\\":\\\"6.1 inch Super Retina XDR\\\",\\\"cpu\\\":\\\"Apple A18\\\",\\\"ram\\\":\\\"8GB\\\",\\\"storage\\\":\\\"128GB\\\"}\",\"colors\":\"Xanh Lưu Ly, Hồng, Xanh Mòng Két, Trắng, Đen\",\"gallery\":\"[\\\"https:\\\\\\/\\\\\\/cdn2.cellphones.com.vn\\\\\\/insecure\\\\\\/rs:fill:358:358\\\\\\/q:90\\\\\\/plain\\\\\\/https:\\\\\\/\\\\\\/cellphones.com.vn\\\\\\/media\\\\\\/catalog\\\\\\/product\\\\\\/i\\\\\\/p\\\\\\/iphone-16-hong_1.png\\\"]\",\"stock\":100,\"product_type\":\"simple\",\"attributes\":null}', '{\"name\":\"iPhone 16 128GB\",\"price\":22990000,\"sale_price\":21990000,\"brand_id\":1,\"category_id\":1,\"product_type\":\"variable\",\"stock\":100}', '2026-04-15 21:32:55'),
