(121, 3, 'Sửa Sản Phẩm', 'admin/product_form.php', 'Cập nhật sản phẩm: Pin sạc dự phòng 25000mAh Type C PD QC 3.0 165W', '{\"id\":90,\"name\":\"Pin sạc dự phòng 25000mAh Type C PD QC 3.0 165W\",\"brand\":\"\",\"price\":\"1600000\",\"sale_price\":\"0.00\",\"ram\":null,\"rom\":null,\"image\":\"https:\\/\\/cdnv2.tgdd.vn\\/mwg-static\\/tgdd\\/Products\\/Images\\/57\\/336355\\/pin-sac-du-phong-25000mah-type-c-pd-qc-3-0-165w-anker-zolo-a1695-kem-cap-bac-1-638942197806891081-750x500.jpg\",\"description\":\"Pin sạc dự phòng 25000mAh Type C PD QC 3.0 165W Anker Zolo A1695 kèm cáp dây rút Type C tiện lợi, chính là giải pháp tối ưu giúp bạn luôn an tâm về nguồn điện, dù ở bất cứ đâu. Với dung lượng pin lớn, tốc độ sạc nhanh chóng và thiết kế thông minh, sản phẩm này hứa hẹn sẽ trở thành người bạn đồng hành không thể thiếu của bạn.\\r\\n• Sạc dự phòng gây ấn tượng với thiết kế tối giản nhưng vẫn toát lên vẻ hiện đại và mạnh mẽ. Lớp vỏ ngoài bền bỉ, chống trầy xước không chỉ bảo vệ thiết bị mà còn mang lại cảm giác cầm nắm chắc chắn và thoải mái. Kích thước nhỏ gọn so với dung lượng pin 25.000 mAh giúp bạn dễ dàng mang theo trong túi xách hay balo mà không cảm thấy vướng víu.\",\"created_at\":\"2026-04-20 09:31:02\",\"brand_id\":25,\"category_id\":18,\"specs\":\"{\\\"screen\\\":\\\"\\\",\\\"cpu\\\":\\\"\\\",\\\"ram\\\":\\\"\\\",\\\"storage\\\":\\\"\\\"}\",\"colors\":null,\"gallery\":null,\"stock\":50,\"product_type\":\"simple\",\"attributes\":null}', '{\"name\":\"Pin sạc dự phòng 25000mAh Type C PD QC 3.0 165W\",\"price\":1600000,\"sale_price\":0,\"brand_id\":25,\"category_id\":20,\"product_type\":\"simple\",\"stock\":50}', '2026-04-20 10:12:28'),
(122, 3, 'Sửa Sản Phẩm', 'admin/product_form.php', 'Cập nhật sản phẩm: Pin sạc dự phòng 10000mAh Type C PD QC 3.0 55W Ugreen', '{\"id\":89,\"name\":\"Pin sạc dự phòng 10000mAh Type C PD QC 3.0 55W Ugreen\",\"brand\":\"\",\"price\":\"990000\",\"sale_price\":\"0.00\",\"ram\":null,\"rom\":null,\"image\":\"https:\\/\\/cdnv2.tgdd.vn\\/mwg-static\\/tgdd\\/Products\\/Images\\/57\\/365424\\/pin-sac-du-phong-10000mah-type-c-pd-qc-3-0-55w-ugreen-pb727-kem-cap-type-c-1-639118142477745653-750x500.jpg\",\"description\":\"Dung lượng pin: 10000 mAh\\r\\nHiệu suất sạc: 56%\\r\\nLõi pin: Li-Ion\\r\\nCông nghệ\\/Tiện ích:\\r\\n- Kiểm soát nhiệt độ, Chống quá tải\\r\\n- Màn hình LED báo hiệu\\r\\n- Power Delivery\\r\\n- Quick Charge 3.0\\r\\n- Sạc nhanh\\r\\nThời gian sạc đầy pin: Khoảng 2 giờ (dùng Adapter 45W)\",\"created_at\":\"2026-04-20 09:28:51\",\"brand_id\":25,\"category_id\":18,\"specs\":\"{\\\"screen\\\":\\\"\\\",\\\"cpu\\\":\\\"\\\",\\\"ram\\\":\\\"\\\",\\\"storage\\\":\\\"\\\"}\",\"colors\":null,\"gallery\":null,\"stock\":50,\"product_type\":\"simple\",\"attributes\":null}', '{\"name\":\"Pin sạc dự phòng 10000mAh Type C PD QC 3.0 55W Ugreen\",\"price\":990000,\"sale_price\":0,\"brand_id\":25,\"category_id\":20,\"product_type\":\"simple\",\"stock\":50}', '2026-04-20 10:12:38'),
