(159, 3, 'Sửa Sản Phẩm', 'admin/product_form.php', 'Cập nhật sản phẩm: Smart Tivi Samsung 4K 55 inch', '{\"id\":46,\"name\":\"Smart Tivi Samsung 4K 55 inch\",\"brand\":\"Apple\",\"price\":\"9990000\",\"sale_price\":\"0.00\",\"ram\":\"\",\"rom\":\"\",\"image\":\"https:\\/\\/cdn2.cellphones.com.vn\\/insecure\\/rs:fill:358:358\\/q:90\\/plain\\/https:\\/\\/cellphones.com.vn\\/media\\/catalog\\/product\\/s\\/m\\/smart-tivi-samsung-qled-55q6fa-4k-55-inch.png\",\"description\":\"Smart Tivi Samsung 4K 55 inch là sản phẩm nổi bật đến từ Apple, được trang bị những công nghệ tiên tiến nhất trong phân khúc giá 29.990.000 VNĐ. screen: 6.7 inches, Dynamic LTPO AMOLED 2X, 120Hz, HDR10+, 1900 nits (peak). cpu: Exynos 2400 (4 nm). ram: 8GB. storage: 128GB. Với thiết kế sang trọng và hiệu năng mạnh mẽ, Smart Tivi Samsung 4K 55 inch mang đến trải nghiệm sử dụng vượt trội cho người dùng Việt Nam. Sản phẩm được bảo hành chính hãng 12 tháng, đổi trả trong 30 ngày nếu có lỗi từ nhà sản xuất. Mua Smart Tivi Samsung 4K 55 inch tại Good Phone để nhận nhiều ưu đãi hấp dẫn và quà tặng giá trị kèm theo.\",\"created_at\":\"2025-12-22 10:45:00\",\"brand_id\":2,\"category_id\":10,\"specs\":\"{\\n    \\\"screen\\\": \\\"6.7 inches, Dynamic LTPO AMOLED 2X, 120Hz, HDR10+, 1900 nits (peak)\\\",\\n    \\\"cpu\\\": \\\"Exynos 2400 (4 nm)\\\",\\n    \\\"ram\\\": \\\"8GB\\\",\\n    \\\"storage\\\": \\\"128GB\\\",\\n    \\\"Camera Sau:\\\": \\\"50 MP, f\\\\\\/1.8; 8 MP, f\\\\\\/2.4; 12 MP, f\\\\\\/2.2\\\",\\n    \\\"Camera Trước:\\\": \\\"12 MP, f\\\\\\/2.2\\\",\\n    \\\"Hỗ trợ Sim:\\\": \\\"2 Sim\\\",\\n    \\\"Công nghệ bảo mật:\\\": \\\"Cảm biến vân tay (dưới màn hình, quang học)\\\",\\n    \\\"Pin:\\\": \\\"4900 mAh, 45W\\\",\\n    \\\"Số ống kính:\\\": \\\"3\\\",\\n    \\\"Độ phân giải & khẩu độ:\\\": \\\"12 MP, f\\\\\\/2.2, 26mm (wide), 1\\\\\\/3.2\\\\\\\", 1.12µm\\\",\\n    \\\"Quay phim camera sau:\\\": \\\"8K@24\\\\\\/30fps, 4K@30\\\\\\/60\\\\\\/120fps, 1080p@30\\\\\\/60\\\\\\/120\\\\\\/240fps; gyro-EIS, HDR10+\\\",\\n    \\\"Các tính năng khác camera sau:\\\": \\\"LED flash, HDR, panorama, Best Face\\\",\\n    \\\"Số ống kính camera trước:\\\": \\\"1\\\",\\n    \\\"Quay phim camera trước:\\\": \\\"4K@30\\\\\\/60fps, 1080p@30\\\\\\/60fps; gyro-EIS, HDR10+\\\",\\n    \\\"Hệ điều hành:\\\": \\\"Android 16, up to 7 major Android upgrades, One UI 8\\\",\\n    \\\"Tốc độ xử lý:\\\": \\\"10-core (1x3.2GHz Cortex-X4 & 2x2.9GHz Cortex-A720 & 3x2.6GHz Cortex-A720 & 4x1.95GHz Cortex-A520)\\\",\\n    \\\"Hỗ trợ thẻ nhớ ngoài:\\\": \\\"Không\\\",\\n    \\\"Cổng kết nối sạc:\\\": \\\"USB Type-C 3.2, OTG\\\",\\n    \\\"Cổng kết nối tai nghe:\\\": \\\"Không\\\",\\n    \\\"Mạng di động:\\\": \\\"GSM \\\\\\/ HSPA \\\\\\/ LTE \\\\\\/ 5G\\\",\\n    \\\"Wifi:\\\": \\\"Wi-Fi 802.11 a\\\\\\/b\\\\\\/g\\\\\\/n\\\\\\/ac\\\\\\/6e, dual-band or tri-band (market\\\\\\/region dependent), Wi-Fi Direct\\\",\\n    \\\"Bluetooth:\\\": \\\"5.4, A2DP, LE\\\",\\n    \\\"GPS:\\\": \\\"GPS, GLONASS, GALILEO, BDS\\\",\\n    \\\"Hỗ trợ SIM:\\\": \\\"2 Sim\\\",\\n    \\\"Dung lượng pin:\\\": \\\"4900 mAh\\\",\\n    \\\"Công nghệ sạc nhanh:\\\": \\\"Sạc có dây 45W, PD, QC2; Sạc không dây 15W, tương thích Qi2 Không dây ngược\\\",\\n    \\\"Thời gian sạc:\\\": \\\"65% trong 30 phút\\\",\\n    \\\"Vật liệu thiết kế:\\\": \\\"Mặt trước bằng kính (Gorilla Glass Victus+), mặt sau bằng kính (Gorilla Glass Victus+), khung nhôm.\\\",\\n    \\\"Kích thước:\\\": \\\"161,3 x 76,6 x 7,4 mm\\\",\\n    \\\"Trọng lượng:\\\": \\\"190 g\\\",\\n    \\\"Khả năng chống nước:\\\": \\\"Đạt chuẩn IP68 chống bụi và chống nước (có thể ngâm trong nước ở độ sâu 1,5m trong 30 phút)\\\"\\n}\",\"colors\":\"\",\"gallery\":\"[]\",\"stock\":100,\"product_type\":\"simple\",\"attributes\":null,\"crawl_status\":\"crawled\"}', '{\"name\":\"Smart Tivi Samsung 4K 55 inch\",\"price\":9990000,\"sale_price\":0,\"brand_id\":2,\"category_id\":10,\"product_type\":\"simple\",\"stock\":100}', '2026-04-28 23:51:16'),
