(251, -270346073, 9999, 'tôi cần tìm điện thoại chơi game', 'user', 0, '2026-03-25 19:57:04'),
(252, 9999, -270346073, 'Dạ vâng ạ! Anh/Chị tìm điện thoại chơi game thì MobileStore có rất nhiều lựa chọn cực đỉnh luôn ạ.<br />\n<br />\nĐể có trải nghiệm mượt mà, cấu hình mạnh mẽ nhất, Em xin giới thiệu ngay 2 &quot;chiến thần&quot; này ạ:<br />\n<br />\n*   <b><a href=\"https://mobilestore.com/iphone-15-pro-max\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 15 Pro Max</a></b>: Chip A17 Bionic Pro siêu mạnh, màn hình ProMotion 120Hz mượt mà. Đảm bảo cân mọi game đồ họa nặng nhất luôn ạ!<br />\n*   <b><a href=\"https://mobilestore.com/samsung-galaxy-s24-ultra\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">Samsung Galaxy S24 Ultra</a></b>: Chip Snapdragon 8 Gen 3 for Galaxy độc quyền, hiệu năng đỉnh cao, màn hình Dynamic AMOLED 2X sáng rực rỡ. Chơi game cực sướng, lại có thêm bút S Pen tiện lợi nữa ạ!<br />\n<br />\nAnh/Chị có đang ưng mẫu nào trong hai siêu phẩm này không ạ? Hoặc mình có mức ngân sách dự kiến không để em tư vấn sát hơn ạ?', 'bot', 0, '2026-03-25 19:57:08'),
(253, -270346073, 9999, 'điện thoại này giá cao quá tôi chỉ có dưới 5 triệu đồng', 'user', 0, '2026-03-25 19:58:16'),
(254, 9999, -270346073, 'Dạ vâng ạ, em hiểu rồi ạ! Dưới 5 triệu đồng để có một chiếc điện thoại chơi game tốt thì đúng là cần cân nhắc kỹ càng hơn một chút ạ.<br />\n<br />\nHiện tại, với phân khúc dưới 5 triệu mà đáp ứng tốt nhu cầu chơi game mượt mà, thì các mẫu điện thoại chuyên game hoặc có cấu hình mạnh mẽ nhất trong tầm giá này bên em đang tạm hết hàng rồi ạ. Rất tiếc chưa có sản phẩm nào để em gửi link cho Anh/Chị ngay được ạ.<br />\n<br />\nAnh/Chị có muốn em tư vấn thêm về các mẫu điện thoại khác trong tầm giá này có hiệu năng ổn định, có thể chơi tốt các game phổ biến không ạ? Hoặc mình có quan tâm đến hãng nào cụ thể không ạ? Em tin là vẫn có những lựa chọn rất hợp lý để Anh/Chị &quot;chiến game&quot; đó ạ!', 'bot', 0, '2026-03-25 19:58:23'),
(255, -270346073, 9999, 'tư vấn mẫu iphone', 'user', 0, '2026-03-25 20:03:56'),
(256, 9999, -270346073, 'Dạ vâng ạ! Anh/Chị muốn tìm mẫu iPhone thì MobileStore là chuẩn bài rồi ạ.&lt;br /&gt;<br />\n&lt;br /&gt;<br />\nTuy nhiên, như Anh/Chị có chia sẻ ngân sách dưới 5 triệu đồng, thì hiện tại các dòng iPhone bên em đang có sẵn như <a href=\"http://localhost:3000/product_detail.php?id=1\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 17 Pro Max</a>, <a href=\"http://localhost:3000/product_detail.php?id=4\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 15 Pro Max</a>, <a href=\"http://localhost:3000/product_detail.php?id=5\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 15</a>, <a href=\"http://localhost:3000/product_detail.php?id=6\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 14 Pro</a> hay <a href=\"http://localhost:3000/product_detail.php?id=7\" target=\"_blank\" style=\"color:#d70018; font-weight:bold;\">iPhone 13</a> đều có giá cao hơn khá nhiều so với mức 5 triệu ạ.&lt;br /&gt;<br />\n&lt;br /&gt;<br />\nRất tiếc là MobileStore chưa có mẫu iPhone nào trong tầm giá dưới 5 triệu để phục vụ Anh/Chị ngay lúc này ạ.&lt;br /&gt;<br />\n&lt;br /&gt;<br />\nKhông biết Anh/Chị có linh động được ngân sách hơn một chút không ạ, hoặc mình có muốn em tư vấn các dòng điện thoại khác có hiệu năng tốt để chơi game trong tầm giá dưới 5 triệu không ạ? Dù không phải iPhone, nhưng vẫn có nhiều lựa chọn rất đáng tiền đó ạ!', 'bot', 0, '2026-03-25 20:04:00'),
(257, -270346073, 9999, 'tư vấn cho tôi mẫu máy ưới 5 triệu', 'user', 0, '2026-03-25 20:08:04'),
(258, 9999, -270346073, 'Dạ vâng ạ, em hiểu rõ là Anh/Chị đang tìm một chiếc điện thoại dưới 5 triệu đồng rồi ạ.&lt;br /&gt;<br />\n&lt;br /&gt;<br />\nHiện tại, với yêu cầu về một chiếc điện thoại chơi game tốt hay có cấu hình thực sự mạnh mẽ trong tầm giá dưới 5 triệu, thì các sản phẩm này bên em đang tạm hết hàng rồi ạ. Rất tiếc là em chưa có mẫu nào để gửi link cho Anh/Chị ngay được ạ.&lt;br /&gt;<br />\n&lt;br /&gt;<br />\nAnh/Chị có muốn em tư vấn các mẫu điện thoại khác trong tầm giá dưới 5 triệu đồng không ạ? Dù không phải là điện thoại chuyên game, nhưng vẫn có nhiều lựa chọn với hiệu năng ổn định, pin trâu và camera đẹp để Anh/Chị sử dụng hàng ngày rất tốt đó ạ! Mình có quan tâm đến hãng nào khác không ạ?', 'bot', 0, '2026-03-25 20:08:09'),
(259, -270346073, 9999, 'tôi cần tìm đồng hồ thông minh', 'user', 0, '2026-03-25 20:08:49'),
