(284, 4, 9999, 'tôi cần tìm lao', 'user', 0, '2026-03-25 20:52:38'),
(285, 9999, 4, 'Dạ anh/chị ơi, anh/chị có thể vui lòng cho em hỏi lại là mình đang tìm <b>loa</b> phải không ạ?<br />\nNếu đúng là loa, MobileStore có rất nhiều mẫu loa chất lượng cao, từ loa di động nhỏ gọn đến loa gaming chuyên dụng hay soundbar sống động để anh/chị chơi game hoặc giải trí đó ạ.<br />\nAnh/chị muốn tìm loại loa nào, dùng cho mục đích gì và ngân sách khoảng bao nhiêu để em tư vấn mẫu phù hợp nhất nha?', 'bot', 0, '2026-03-25 20:52:42'),
(286, 4, 9999, 'giải trí', 'user', 0, '2026-03-25 20:53:11'),
(287, 9999, 4, 'Dạ vâng, để giải trí thì MobileStore có rất nhiều lựa chọn loa cực hay đó ạ!<br />\nNếu anh/chị muốn nghe nhạc tại nhà, xem phim với âm thanh sống động, em đề xuất các dòng loa Soundbar hoặc loa Bluetooth công suất lớn. Còn nếu thích mang đi du lịch, dã ngoại thì các mẫu loa Bluetooth di động sẽ rất tiện lợi ạ.<br />\nAnh/chị muốn tìm loa dùng trong không gian như thế nào và ngân sách khoảng bao nhiêu để em tư vấn mẫu phù hợp nhất nha?', 'bot', 0, '2026-03-25 20:53:15'),
(288, 4, 9999, 'tôi cần tìm tai nghe bluetooth', 'user', 0, '2026-03-25 20:53:29'),
(289, 9999, 4, 'Dạ vâng, tai nghe Bluetooth là lựa chọn tuyệt vời để giải trí đó ạ! MobileStore hiện có sẵn các mẫu tai nghe Bluetooth cao cấp với chất lượng âm thanh đỉnh cao và nhiều tính năng hiện đại.<br />\nAnh/chị tham khảo ngay nhé:<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=69\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">Tai nghe Bluetooth Apple AirPods 4</a></b><br />\n    *   Giá chỉ: <b>3.490.000đ</b><br />\n    *   Thiết kế nhỏ gọn, kết nối nhanh chóng, âm thanh Apple đặc trưng.<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=34\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">Tai nghe Bluetooth AirPods Pro 2</a></b><br />\n    *   Giá chỉ: <b>5.490.000đ</b><br />\n    *   Chống ồn chủ động đỉnh cao, xuyên âm thông minh, chất âm sống động.<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=82\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">Tai nghe Sony WF-1000XM5</a></b><br />\n    *   Giá chỉ: <b>6.990.000đ</b><br />\n    *   Chất âm Hi-Res, chống ồn hàng đầu thế giới, thiết kế in-ear gọn nhẹ.<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=36\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">Tai nghe Sony WH-1000XM5</a></b><br />\n    *   Giá chỉ: <b>7.490.000đ</b><br />\n    *   Tai nghe chụp tai, chống ồn tuyệt đối, nghe nhạc cực đã, pin cực trâu.<br />\nAnh/chị thích mẫu nào hay có yêu cầu về giá, về tính năng (ví dụ: chống ồn, thời lượng pin, thiết kế) để em tư vấn kỹ hơn nha!', 'bot', 0, '2026-03-25 20:53:33'),
(290, 4, 9999, 'ipad', 'user', 0, '2026-03-25 20:55:32'),
(291, 9999, 4, 'Dạ vâng, anh/chị tìm iPad để giải trí là chuẩn rồi ạ! MobileStore có sẵn rất nhiều dòng iPad đời mới nhất, hiệu năng mạnh mẽ, màn hình đẹp tuyệt vời để anh/chị thỏa sức xem phim, nghe nhạc, chơi game hay làm việc đó ạ.<br />\nAnh/chị tham khảo các mẫu iPad đang có tại cửa hàng em nhé:<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=37\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">iPad Pro M2</a></b><br />\n    *   Giá chỉ từ: <b>24.990.000đ</b><br />\n    *   Chip M2 siêu mạnh, màn hình Liquid Retina XDR sắc nét, lý tưởng cho công việc và giải trí cao cấp.<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=38\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">iPad Air 5</a></b><br />\n    *   Giá chỉ từ: <b>16.990.000đ</b><br />\n    *   Chip M1 mạnh mẽ, thiết kế mỏng nhẹ, màu sắc đa dạng, cân bằng hoàn hảo giữa hiệu năng và tính di động.<br />\n*   <b><a href=\"http://localhost:3000/product_detail.php?id=70\" target=\"_blank\" style=\"color:#0d47a1; font-weight:bold;\">iPad Gen 10</a></b><br />\n    *   Giá chỉ từ: <b>12.990.000đ</b><br />\n    *   Thiết kế trẻ trung, màn hình lớn, hiệu năng tốt, lựa chọn kinh tế cho nhu cầu giải trí và học tập hàng ngày.<br />\nAnh/chị đang có nhu cầu dùng iPad cho mục đích chính là gì (xem phim, đọc sách, chơi game, học tập/làm việc) hay ngân sách dự kiến khoảng bao nhiêu để em tư vấn mẫu phù hợp nhất nha?', 'bot', 0, '2026-03-25 20:55:36'),
