(1, 'iPhone 17 Pro Max', 'Apple', 34990000, 0.00, '12', '512', '1766198634_iphone-17-pro-max_3.webp', 'iPhone 17 Pro Max là sản phẩm nổi bật đến từ Apple, được trang bị những công nghệ tiên tiến nhất trong phân khúc giá 34.990.000 VNĐ. screen: 6.7 inch Super Retina XDR OLED, 120Hz. cpu: Apple A17 Pro. ram: 12GB. storage: 512GB. Với thiết kế sang trọng và hiệu năng mạnh mẽ, iPhone 17 Pro Max mang đến trải nghiệm sử dụng vượt trội cho người dùng Việt Nam. Sản phẩm được bảo hành chính hãng 12 tháng, đổi trả trong 30 ngày nếu có lỗi từ nhà sản xuất. Mua iPhone 17 Pro Max tại Good Phone để nhận nhiều ưu đãi hấp dẫn và quà tặng giá trị kèm theo.', '2025-12-19 09:06:29', 1, 1, '{\n    \"screen\": \"6.7 inch Super Retina XDR OLED, 120Hz\",\n    \"cpu\": \"Apple A17 Pro\",\n    \"ram\": \"12GB\",\n    \"storage\": \"512GB\",\n    \"Camera sau\": \"48 MP (chính) + 12 MP (góc siêu rộng) + 12 MP (tele 5x)\",\n    \"Camera trước\": \"12 MP\",\n    \"Pin\": \"4685 mAh, sạc 27W\",\n    \"Hệ điều hành\": \"iOS 17\",\n    \"Kết nối\": \"5G, WiFi 6, Bluetooth 5.3, NFC\"\n}', '', '[]', 100, 'simple', NULL, 'fallback'),
(2, 'Samsung Galaxy S24 Ultra', 'Samsung', 290000, 0.00, '', '', '1766198554_samsung-galaxy-s24-ultra-cu-tim-titan.jpg.webp', 'Samsung Galaxy S24 Ultra là sản phẩm nổi bật đến từ Samsung, được trang bị những công nghệ tiên tiến nhất trong phân khúc giá 29.990.000 VNĐ. screen: 6.8 inches, Dynamic LTPO AMOLED 2X, 120Hz, 480Hz PWM, HDR10+, 2600 nits (peak). cpu: Qualcomm SM8650-AC Snapdragon 8 Gen 3 (4 nm). ram: 12GB. storage: 256GB. Với thiết kế sang trọng và hiệu năng mạnh mẽ, Samsung Galaxy S24 Ultra mang đến trải nghiệm sử dụng vượt trội cho người dùng Việt Nam. Sản phẩm được bảo hành chính hãng 12 tháng, đổi trả trong 30 ngày nếu có lỗi từ nhà sản xuất. Mua Samsung Galaxy S24 Ultra tại Good Phone để nhận nhiều ưu đãi hấp dẫn và quà tặng giá trị kèm theo.', '2025-12-19 09:06:29', 2, 1, '{\n    \"screen\": \"6.8 inches, Dynamic LTPO AMOLED 2X, 120Hz, 480Hz PWM, HDR10+, 2600 nits (peak)\",\n    \"cpu\": \"Qualcomm SM8650-AC Snapdragon 8 Gen 3 (4 nm)\",\n    \"ram\": \"12GB\",\n    \"storage\": \"256GB\",\n    \"Camera Sau:\": \"200 MP, f\\/1.7; 10 MP, f\\/2.4; 50 MP, f\\/3.4; 12 MP, f\\/2.2\",\n    \"Camera Trước:\": \"12 MP, f\\/2.2\",\n    \"Hỗ trợ Sim:\": \"1 nano + 1 eSim\",\n    \"Công nghệ bảo mật:\": \"Vân tay (dưới màn hình, siêu âm)\",\n    \"Pin:\": \"5000mAh, 45W\",\n    \"Số ống kính:\": \"4\",\n    \"Độ phân giải & khẩu độ:\": \"12 MP, f\\/2.2, 26mm (wide), 1\\/3.2\\\", 1.12µm, dual pixel PDAF\",\n    \"Quay phim camera sau:\": \"8K@24\\/30fps, 4K@30\\/60\\/120fps, 1080p@30\\/60\\/120\\/240fps, HDR10+, stereo sound rec., gyro-EIS\",\n    \"Số ống kính camera trước:\": \"1\",\n    \"Quay phim camera trước:\": \"4K@30\\/60fps, 1080p@30fps\",\n    \"Hệ điều hành:\": \"Android 14, up to 7 major Android upgrades, One UI 6.1.1\",\n    \"Tốc độ xử lý:\": \"8-core (1x3.39GHz Cortex-X4 & 3x3.1GHz Cortex-A720 & 2x2.9GHz Cortex-A720 & 2x2.2GHz Cortex-A520)\",\n    \"Hỗ trợ thẻ nhớ ngoài:\": \"không\",\n    \"Cổng kết nối sạc:\": \"USB Type-C 3.2, DisplayPort 1.2, OTG\",\n    \"Cổng kết nối tai nghe:\": \"Không\",\n    \"Mạng di động:\": \"GSM \\/ CDMA \\/ HSPA \\/ EVDO \\/ LTE \\/ 5G\",\n    \"Wifi:\": \"Wi-Fi 802.11 a\\/b\\/g\\/n\\/ac\\/6e\\/7, tri-band, Wi-Fi Direct\",\n    \"Bluetooth:\": \"5.3, A2DP, LE\",\n    \"GPS:\": \"GPS, GLONASS, BDS, GALILEO, QZSS\",\n    \"Hỗ trợ SIM:\": \"1 nano + 1 eSim\",\n    \"Dung lượng pin:\": \"5000mAh\",\n    \"Công nghệ sạc nhanh:\": \"Sạc nhanh 45W\",\n    \"Thời gian sạc:\": \"65% trong 30 phút\",\n    \"Vật liệu thiết kế:\": \"Mặt kính trước (Corning Gorilla Armor), mặt kính sau (Corning Gorilla Armor), khung titan (cấp 2)\",\n    \"Kích thước:\": \"162,3 x 79 x 8,6 mm\",\n    \"Trọng lượng:\": \"232 g hoặc 233 g\",\n    \"Khả năng chống nước:\": \"Chống bụi và chống nước theo tiêu chuẩn IP68 (có thể ngâm ở độ sâu 1,5m trong 30 phút)\",\n    \"Tính năng khác:\": \"Bút cảm ứng (Tích hợp Bluetooth, gia tốc kế, con quay hồi chuyển)\"\n}', '', '[]', 100, 'simple', NULL, 'crawled'),
